import MapboxDraw from "@mapbox/mapbox-gl-draw";
import {
  createSnapList,
  getFormattedSnapVertexPriorityDistance,
  getGuideFeature,
  IDS,
  snap,
  addSnapSymbol,
  updateSnapSymbol,
  deleteSnapSymbol
} from "./../utils/index.js";

const { doubleClickZoom } = MapboxDraw.lib;
const Constants = MapboxDraw.constants;
const DirectSelect = MapboxDraw.modes.direct_select;
const SnapDirectSelect = { ...DirectSelect };

SnapDirectSelect.onSetup = function (opts) {
  addSnapSymbol(this.map);
  const featureId = opts.featureId;
  const feature = this.getFeature(featureId);

  if (!feature) {
    throw new Error("You must provide a featureId to enter direct_select mode");
  }

  if (feature.type === Constants.geojsonTypes.POINT) {
    throw new TypeError("direct_select mode doesn't handle point features");
  }

  const [snapList, vertices] = createSnapList(
    this.map,
    this._ctx.api,
    { currentFeature: feature },
    this._ctx.options.snapOptions?.snapGetFeatures
  );

  const verticalGuide = this.newFeature(getGuideFeature(IDS.VERTICAL_GUIDE));
  const horizontalGuide = this.newFeature(
    getGuideFeature(IDS.HORIZONTAL_GUIDE)
  );

  this.addFeature(verticalGuide);
  this.addFeature(horizontalGuide);

  const state = {
    map: this.map,
    featureId,
    feature,
    dragMoveLocation: opts.startPos || null,
    dragMoving: false,
    canDragMove: false,
    selectedCoordPaths: opts.coordPath ? [opts.coordPath] : [],
    vertices,
    snapList,
    verticalGuide,
    horizontalGuide,
  };

  state.options = this._ctx.options;

  this.setSelectedCoordinates(
    this.pathsToCoordinates(featureId, state.selectedCoordPaths)
  );
  this.setSelected(featureId);
  doubleClickZoom.disable(this);

  this.setActionableState({
    trash: true,
  });

  const optionsChangedCallback = (options) => {
    state.options = options;
  };

  // for removing listener later on close
  state["optionsChangedCallback"] = optionsChangedCallback;
  this.map.on("draw.snap.options_changed", optionsChangedCallback);

  return state;
};

SnapDirectSelect.dragVertex = function (state, e) {
  const draw = this._ctx.api;
  const params = {
    currentFeature: state.feature,
    snapFeatures: state.options.snapOptions?.snapFeatures
  };
  const [snapList, vertices] = createSnapList(
    this.map,
    draw,
    params,
    this._ctx.options.snapOptions?.snapGetFeatures
  );
  state.vertices = vertices;
  state.snapList = snapList;

  // 动态调整snapVertexPriorityDistance
  state.options.snapOptions.snapVertexPriorityDistance = getFormattedSnapVertexPriorityDistance(this.map.getZoom());

  const { lng, lat } = snap(state, e);
  updateSnapSymbol(this.map, { lng, lat }, e.lngLat);
  state.feature.updateCoordinate(state.selectedCoordPaths[0], lng, lat);
};

SnapDirectSelect.onStop = function (state) {
  deleteSnapSymbol(this.map);
  this.deleteFeature(IDS.VERTICAL_GUIDE, { silent: true });
  this.deleteFeature(IDS.HORIZONTAL_GUIDE, { silent: true });

  // remove moveend callback
  //   this.map.off("moveend", state.moveendCallback);
  this.map.off("draw.snap.options_changed", state.optionsChangedCallback);

  // This relies on the the state of SnapPolygonMode being similar to DrawPolygon
  DirectSelect.onStop.call(this, state);
};

export default SnapDirectSelect;
